import{_ as t,o,c as n,a5 as s}from"./chunks/framework.CcrBcQWS.js";const u=JSON.parse('{"title":"How to Connect to the RBQ Development PC","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/release-note/how-to-connect-rbq-dev-pc.md","filePath":"software/release-note/how-to-connect-rbq-dev-pc.md","lastUpdated":1787021357000}'),a={name:"software/release-note/how-to-connect-rbq-dev-pc.md"};function i(l,e,r,c,p,h){return o(),n("div",null,[...e[0]||(e[0]=[s(`<hr><h1 id="how-to-connect-to-the-rbq-development-pc" tabindex="-1">How to Connect to the RBQ Development PC <a class="header-anchor" href="#how-to-connect-to-the-rbq-development-pc" aria-label="Permalink to &quot;How to Connect to the RBQ Development PC&quot;">​</a></h1><p>This guide explains how to connect to the <strong>RBQ Dev PC</strong> using <strong>NoMachine</strong> for remote desktop access.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>The <strong>RBQ Dev PC</strong> is the on-robot <strong>User-PC module</strong> — the machine you develop on. The User-PC module is an <strong>option</strong>, so your robot may not have one.</p></div></div><h2 id="step-1-download-nomachine" tabindex="-1">Step 1. Download NoMachine <a class="header-anchor" href="#step-1-download-nomachine" aria-label="Permalink to &quot;Step 1. Download NoMachine&quot;">​</a></h2><ol><li><p>Download the NoMachine application from the official website: 🔗 <a href="https://www.nomachine.com/" target="_blank" rel="noreferrer">NoMachine Download Page</a></p></li><li><p>Be sure to select the correct version for your platform (Linux).</p></li></ol><h2 id="step-2-install-nomachine-on-the-rbq-dev-pc" tabindex="-1">Step 2. Install NoMachine on the RBQ Dev PC <a class="header-anchor" href="#step-2-install-nomachine-on-the-rbq-dev-pc" aria-label="Permalink to &quot;Step 2. Install NoMachine on the RBQ Dev PC&quot;">​</a></h2><p>Open a terminal and run the following commands to install NoMachine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zxvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/nomachine_latest_version.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/NX/nxserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/NX/bin/nxserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre></div><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Use <code>nxserver --status</code> to verify that the server is running properly.</p></div></div><h2 id="step-3-connect-from-your-development-pc" tabindex="-1">Step 3. Connect from Your Development PC <a class="header-anchor" href="#step-3-connect-from-your-development-pc" aria-label="Permalink to &quot;Step 3. Connect from Your Development PC&quot;">​</a></h2><ol><li><p>Make sure your <strong>development PC is connected to the same network</strong> as the RBQ (via Ethernet or SSH-enabled connection).</p></li><li><p>Launch the <strong>NoMachine app</strong> on your PC.</p></li><li><p>Click <strong>&quot;Add&quot;</strong> to create a new connection.</p></li><li><p>Fill in the following details:</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name : rbq</span></span>
<span class="line"><span>Host : 192.168.0.13</span></span></code></pre></div><p>The U-PC default address is <code>192.168.0.13</code>. If you cannot connect, attach a monitor to the U-PC and check its current IP. If it is using a different address, set it statically to <code>192.168.0.13</code>.</p><p>Please <a href="/RBQ/nightly/manual/troubleshooting/error-reporting.html">contact us</a> if it still does not connect.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Recommended Nomachine Display Resolution Settings:</p><ul><li>✅ Enable: <strong>&quot;Scale the remote desktop to fit the window&quot;</strong></li><li>🚫 Disable: <strong>&quot;Resize the remote display&quot;</strong></li></ul></div></div><h2 id="you-re-now-connected" tabindex="-1">You&#39;re Now Connected! <a class="header-anchor" href="#you-re-now-connected" aria-label="Permalink to &quot;You&#39;re Now Connected!&quot;">​</a></h2><p>You can now control and develop on the <strong>RBQ Dev PC</strong> remotely via a user-friendly desktop interface.</p><p>Enjoy your development workflow!</p>`,19)])])}const v=t(a,[["render",i]]);export{u as __pageData,v as default};
